// Same generated bytes, same traced host, same requests for A/base, B/#91 and C/#93.
import assert from 'node:assert/strict';
import { spawn, execFileSync } from 'node:child_process';
import { once } from 'node:events';
import { mkdir, readFile, writeFile, mkdtemp, copyFile } from 'node:fs/promises';
import { createServer } from 'node:net';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { setTimeout as sleep } from 'node:timers/promises';
import { createHash, randomUUID } from 'node:crypto';

const ownWeb = fileURLToPath(new URL('..', import.meta.url));
const helper = path.join(ownWeb, 'tests/blocker_trace_host.py');
const python = process.env.EDU_TEST_PYTHON;
assert.ok(python);
const roots = {
  A: process.env.EDU_TRACE_ROOT_A || 'D:/AI/weiran/.worktrees/edu-return-reuse-baseline157',
  B: process.env.EDU_TRACE_ROOT_B || 'D:/AI/weiran/.worktrees/edu-diagnosis-return-reuse',
  C:
    process.env.EDU_TRACE_ROOT_C ||
    'D:/AI/weiran/.worktrees/edu-analysis-perf-integration-20261114',
};
const expected = {
  A: '15788491b536d408005030ddbed2cee2d1a9f6b2',
  B: 'da7c27920f3c40cf53e57efafa805c73894a3e84',
  C: '13cdc04184f5d96e13bddcd31ba2b5da83a8be8e',
};
const mode = process.env.EDU_TRACE_HOST_MODE || 'stdin_thread';
const round = process.env.EDU_TRACE_ROUND || 'before';
const artifacts = path.join(ownWeb, 'artifacts/504-diagnosis', round);
await mkdir(artifacts, { recursive: true });
const temporary = await mkdtemp(path.join(tmpdir(), 'edu-504-control-'));
const data = process.env.EDU_TRACE_DATA || path.join(temporary, 'data');
const envFor = (repo) => ({
  ...process.env,
  PYTHONPATH: `${repo};${path.join(repo, 'apps/api')}`,
  PYTHONUTF8: '1',
  EDU_TRACE_SOURCE: repo,
});
if (!process.env.EDU_TRACE_DATA)
  execFileSync(python, [helper, '--make-data', data], {
    cwd: roots.C,
    env: envFor(roots.C),
    windowsHide: true,
  });
const hashes = Object.fromEntries(
  await Promise.all(
    ['72', '53', '96', '105'].map(async (n) => [
      n,
      createHash('sha256')
        .update(await readFile(path.join(data, n + '.xlsx')))
        .digest('hex'),
    ]),
  ),
);
const result = { mode, round, dataDirectory: data, dataSha256: hashes, versions: {}, runs: [] };
const caseSpec = (
  process.env.EDU_TRACE_CASES ||
  '72:direct:single,72:relay:single,53:direct:single,53:relay:single,72:direct:concurrent,72:relay:concurrent,105:direct:single,105:relay:single'
)
  .split(',')
  .map((s) => s.split(':'));
const selected = (process.env.EDU_TRACE_ROOTS || 'A,B,C').split(',');
const save = () =>
  writeFile(path.join(artifacts, 'results.json'), JSON.stringify(result, null, 2) + '\n');
async function freePort() {
  const s = createServer();
  s.listen(0, '127.0.0.1');
  await once(s, 'listening');
  const port = s.address().port;
  await new Promise((r) => s.close(r));
  return port;
}

for (const label of selected) {
  const repo = roots[label];
  result.versions[label] = execFileSync('git', ['rev-parse', 'HEAD'], {
    cwd: repo,
    encoding: 'utf8',
    windowsHide: true,
  }).trim();
  assert.equal(result.versions[label], expected[label]);
  for (const [size, transport, load] of caseSpec) {
    const key = `${label}-${size}-${transport}-${load}`;
    const directory = path.join(temporary, key);
    await mkdir(directory, { recursive: true });
    const run = { key, label, size, transport, load, directory, requests: [], stages: [] };
    result.runs.push(run);
    let frontend, connection;
    const host = spawn(
      python,
      ['-u', helper, '--directory', directory, '--data', data, '--case', size, '--mode', mode],
      { cwd: repo, env: envFor(repo), stdio: ['pipe', 'pipe', 'pipe'], windowsHide: true },
    );
    run.hostPid = host.pid;
    let stdout = '',
      stderr = '';
    host.stderr.on('data', (chunk) => {
      stderr = (stderr + chunk.toString()).slice(-4000);
    });
    const ready = new Promise((resolve, reject) => {
      const timer = setTimeout(() => reject(Error('host readiness timeout')), 240000);
      host.stdout.on('data', (chunk) => {
        stdout += chunk.toString();
        for (const line of stdout.split('\n')) {
          try {
            const v = JSON.parse(line);
            if (v.ready) {
              clearTimeout(timer);
              resolve(v.connection);
            }
          } catch {}
        }
      });
      host.once('exit', (code) => {
        clearTimeout(timer);
        reject(Error(`host exited ${code}: ${stderr}`));
      });
    });
    ready.catch(() => {});
    console.log(JSON.stringify({ starting: key, mode }));
    try {
      connection = JSON.parse(await readFile(await ready, 'utf8'));
      const session = path.join(directory, 'web-session.private.json');
      await writeFile(
        session,
        JSON.stringify({ synthetic_only: true, access_token: connection.bearer_token }),
      );
      const port = await freePort(),
        origin = `http://127.0.0.1:${port}`;
      frontend = spawn(
        process.execPath,
        [
          'node_modules/next/dist/bin/next',
          'start',
          '--hostname',
          '127.0.0.1',
          '--port',
          String(port),
        ],
        {
          cwd: path.join(repo, 'apps/web'),
          env: {
            ...envFor(repo),
            EDU_TEST_MODE: '1',
            EDU_AI_SYNTHETIC_MODE: '1',
            EDU_TEST_SESSION_FILE: session,
            EDU_API_ORIGIN: connection.api_origin,
            NEXT_TELEMETRY_DISABLED: '1',
          },
          stdio: 'ignore',
          windowsHide: true,
        },
      );
      run.frontendPid = frontend.pid;
      run.origin = origin;
      await save();
      for (let i = 0; ; i++) {
        assert.ok(i < 100);
        assert.equal(frontend.exitCode, null);
        if ((await fetch(origin, { signal: AbortSignal.timeout(1000) }).catch(() => null))?.ok)
          break;
        await sleep(200);
      }
      const batch = connection.batches[size];
      const prefix = `/batches/${batch.batch_id}`;
      async function request(name, via, route, body, deadline = 55000) {
        const started = performance.now();
        const row = { name, via, ms: null, status: null };
        run.requests.push(row);
        try {
          const response = await fetch(
            (via === 'direct' ? connection.api_origin + '/api/v1/edu' : origin + '/api/edu') +
              route,
            {
              method: body === undefined ? 'GET' : 'POST',
              headers: {
                ...(via === 'direct' ? { Authorization: 'Bearer ' + connection.bearer_token } : {}),
                ...(body === undefined ? {} : { 'content-type': 'application/json' }),
                ...(route.endsWith('/discoveries/query')
                  ? { 'X-EDU-Diagnosis-Session': randomUUID() }
                  : {}),
              },
              body: body === undefined ? undefined : JSON.stringify(body),
              signal: AbortSignal.timeout(deadline),
            },
          );
          const value = await response.json();
          row.status = response.status;
          row.code = value.error?.code ?? null;
          row.retained = value.retained_count ?? null;
          row.taskId = value.task_id ?? null;
        } catch (error) {
          row.failure = error.name + ': ' + error.message;
        }
        row.ms = Math.round(performance.now() - started);
        console.log(JSON.stringify({ key, ...row }));
        await save();
        return row;
      }
      const question = {
        snapshot_id: batch.snapshot_id,
        question: '帮我分析一下',
        idempotency_key: 'trace-unknown-question',
      };
      // Unambiguous before-compute controls; no discovery process has been started yet.
      await request('unknown-alone', 'direct', prefix + '/ai-investigation-tasks', question, 15000);
      await request('unknown-alone', 'relay', prefix + '/ai-investigation-tasks', question, 15000);
      await request('ordinary-before', 'direct', '/me', undefined, 10000);
      const first = request(
        'first-discovery',
        transport,
        prefix + '/discoveries/query',
        { snapshot_id: batch.snapshot_id },
        transport === 'direct' ? 45000 : 50000,
      );
      if (load === 'concurrent') {
        await sleep(500);
        await Promise.all([
          request('unknown-concurrent', 'direct', prefix + '/ai-investigation-tasks', question),
          request('unknown-concurrent', 'relay', prefix + '/ai-investigation-tasks', question),
          request('ordinary-concurrent', 'direct', '/me'),
        ]);
      }
      await first;
      run.finished = true;
    } catch (error) {
      run.failure = String(error);
      console.log(JSON.stringify({ key, failure: run.failure }));
    } finally {
      await writeFile(path.join(directory, 'stop.flag'), 'stop');
      if (host.exitCode === null) host.stdin.end('stop\n');
      await Promise.race([once(host, 'exit').catch(() => {}), sleep(10000)]);
      if (host.exitCode === null) {
        // This is the still-live PID returned by our own spawn, never a process name search.
        if (process.platform === 'win32') {
          try {
            execFileSync('taskkill.exe', ['/PID', String(host.pid), '/T', '/F'], {
              windowsHide: true,
              stdio: 'ignore',
            });
          } catch (error) {
            // The child can finish between checking exitCode and taskkill.
            run.cleanupExit = error.status;
          }
        } else host.kill();
        run.forcedOwnedHostStop = true;
      }
      if (frontend?.exitCode === null) frontend.kill();
      const trace = await readFile(path.join(directory, 'phases.jsonl'), 'utf8').catch(() => '');
      run.stages = trace
        .trim()
        .split('\n')
        .filter(Boolean)
        .map((line) => JSON.parse(line));
      await copyFile(
        path.join(directory, 'stacks.txt'),
        path.join(artifacts, key + '-stacks.txt'),
      ).catch(() => {});
      await writeFile(
        path.join(artifacts, key + '-phases.json'),
        JSON.stringify(run.stages, null, 2) + '\n',
      );
      await save();
    }
  }
}
console.log(
  JSON.stringify({
    output: path.join(artifacts, 'results.json'),
    dataDirectory: data,
    runs: result.runs.length,
  }),
);
